  useEffect(()=>{if(!token)return;load().catch(e=>setStatus(e.message));const refresh=(event:Event)=>{if((event as CustomEvent).detail?.keepTransactionOrder)return;load()};window.addEventListener("kirana:data-changed",refresh);return()=>window.removeEventListener("kirana:data-changed",refresh)},[token]);
  function applyPreset(value:string){const end=new Date(`${today}T12:00:00`),start=new Date(end);if(value==="yesterday"){start.setDate(start.getDate()-1);end.setDate(end.getDate()-1)}else if(value==="last_week")start.setDate(start.getDate()-6);else if(value==="this_month")start.setDate(1);setPreset(value);setFromDate(start.toISOString().slice(0,10));setToDate(end.toISOString().slice(0,10))}
  async function save(){if(!editing)return;setBusy(true);setStatus("Saving changes and recalculating inventory…");try{const transactionId=editing[kind==="sales"?"sale_id":"purchase_id"];await req(`/businesses/${ctx.business.id}/${kind}/${transactionId}/lines/${editing.line_id}`,{method:"PATCH",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({quantity:Number(editing.quantity),total_price:Number(editing.total_price)})});setEditing(null);await load();window.dispatchEvent(new Event("kirana:data-changed"));setStatus("Changes saved. Inventory and reports were recalculated.")}catch(e:any){setStatus(e.message)}finally{setBusy(false)}}
