  async function remove(row:Row){const transactionId=row[kind==="sales"?"sale_id":"purchase_id"];if(!window.confirm(`Delete only the selected ${row.product_name} row? Its inventory movement will be reversed.`))return;setBusy(true);setStatus("Deleting selected row and reversing its inventory…");try{await req(`/businesses/${ctx.business.id}/${kind}/${transactionId}/lines/${row.line_id}`,{method:"DELETE",headers});await load();window.dispatchEvent(new Event("kirana:data-changed"));setStatus("Selected row deleted. Other records were kept.")}catch(e:any){setStatus(e.message)}finally{setBusy(false)}}
