  async function upload(f:File){setBusy(true);setStatus(`Uploading ${f.name}…`);try{if(f.name.toLowerCase().endsWith(".csv")){const raw=await f.text();const parsed=raw.split(/\r?\n/).filter(Boolean).slice(1).map(x=>{const [customer_name,amount,entry_type]=x.split(",");return {customer_name,amount:Number(amount),entry_type:entry_type||"credit_sale"}});setRows(parsed);setStatus("CSV processed. Review before posting.");return}const stores=await req(`/businesses/${ctx.business.id}/stores`,{headers});const fd=new FormData();fd.append("file",f);const d=await req(`/businesses/${ctx.business.id}/images?store_id=${stores[0].id}&document_type=udhaar`,{method:"POST",headers,body:fd});setStatus("Image uploaded. AI is extracting udhaar rows…");const x=await req(`/businesses/${ctx.business.id}/images/${d.id}/extract`,{method:"POST",headers});setRows(x.data?.rows||[]);setStatus("Udhaar image processed. Review before posting.")}catch(e:any){setStatus(`Upload failed: ${e.message}`)}finally{setBusy(false)}}
