function CustomerUdhaarTable(){
  const today=todayInput(),{headers,req,token}=SessionApi(),[rows,setRows]=useState<Row[]>([]),[preset,setPreset]=useState("today"),[fromDate,setFromDate]=useState(today),[toDate,setToDate]=useState(today),[status,setStatus]=useState("");
  async function load(){const business=(await req("/businesses",{headers}))[0];if(!business)return;setRows(await req(`/businesses/${business.id}/credit-details?party_type=customer`,{headers}))}
  useEffect(()=>{if(!token)return;load().catch(e=>setStatus(e.message));const refresh=()=>load().catch(e=>setStatus(e.message));window.addEventListener("kirana:data-changed",refresh);return()=>window.removeEventListener("kirana:data-changed",refresh)},[token]);
  function applyPreset(value:string){const end=new Date(`${today}T12:00:00`),start=new Date(end);if(value==="yesterday"){start.setDate(start.getDate()-1);end.setDate(end.getDate()-1)}else if(value==="last_week")start.setDate(start.getDate()-6);else if(value==="this_month")start.setDate(1);setPreset(value);setFromDate(start.toISOString().slice(0,10));setToDate(end.toISOString().slice(0,10))}
  const visible=rows.filter(row=>String(row.date).slice(0,10)>=fromDate&&String(row.date).slice(0,10)<=toDate),total=visible.reduce((sum,row)=>sum+Number(row.amount),0);
  return <section className="panel customer-udhaar-table"><div className="panel-head"><div><h2>Udhaar records</h2><p>Selected date range mein customer se lena hai</p></div><strong>{money(total)}</strong></div><div className="transaction-filters"><label>Quick range<select value={preset} onChange={e=>applyPreset(e.target.value)}><option value="today">Today</option><option value="yesterday">Yesterday</option><option value="last_week">Last week</option><option value="this_month">This month</option><option value="custom">Custom</option></select></label><label>From<input type="date" max={today} value={fromDate} onChange={e=>{setPreset("custom");setFromDate(e.target.value)}}/></label><label>To<input type="date" min={fromDate} max={today} value={toDate} onChange={e=>{setPreset("custom");setToDate(e.target.value)}}/></label></div><div className="udhaar-record-table"><div className="udhaar-record-row head"><b>Date</b><b>Customer name</b><b>Amount</b></div>{visible.map(row=><div className="udhaar-record-row" key={row.id}><span>{new Date(`${String(row.date).slice(0,10)}T12:00:00`).toLocaleDateString("en-IN")}</span><b>{row.party_name}</b><strong>{money(Number(row.amount))}</strong></div>)}</div>{!visible.length&&<p className="empty">Is date range mein koi Udhaar record nahi hai.</p>}{status&&<p className="entry-status">{status}</p>}</section>
}

