function LegacyPurchaseEntry(){
  const {headers,req,token}=SessionApi(),[ctx,setCtx]=useState<Row>({}),[supplier,setSupplier]=useState(""),[vendorName,setVendorName]=useState(""),[method,setMethod]=useState<"table"|"upload"|"text">("table"),[rows,setRows]=useState<Row[]>([{product_name:"",quantity:1,unit_price:0,unit:""}]),[text,setText]=useState("Coca Cola 2L 12 80"),[status,setStatus]=useState(""),[busy,setBusy]=useState(false);
  useEffect(()=>{if(!token)return;(async()=>{const b=(await req("/businesses",{headers}))[0],stores=await req(`/businesses/${b.id}/stores`,{headers}),suppliers=await req(`/businesses/${b.id}/suppliers`,{headers}),products=await req(`/businesses/${b.id}/products`,{headers});setCtx({business:b,store:stores[0],suppliers,products});setSupplier(suppliers[0]?.id||"")})().catch(e=>setStatus(e.message))},[token]);
  function update(i:number,k:string,v:any){setRows(rows.map((r,n)=>n===i?{...r,[k]:v}:r))}
  async function parse(){setBusy(true);setStatus("AI is mapping purchase rows…");try{const d=await req(`/businesses/${ctx.business.id}/ai/parse-text`,{method:"POST",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({entry_type:"stock",text})});setRows(d.rows||[]);setStatus("Purchase mapped. Review the rows before submitting.")}catch(e:any){setStatus(e.message)}finally{setBusy(false)}}
  async function upload(f:File){setBusy(true);setStatus(`Uploading ${f.name}…`);try{if(f.name.endsWith(".csv")){const raw=await f.text();setRows(raw.split(/\r?\n/).filter(Boolean).slice(1).map(x=>{const [product_name,quantity,unit_price]=x.split(",");return {product_name,quantity:Number(quantity),unit_price:Number(unit_price)}}));setStatus("CSV processed. Add or select the vendor, then review purchase rows.");return}const fd=new FormData();fd.append("file",f);const d=await req(`/businesses/${ctx.business.id}/images?store_id=${ctx.store.id}&document_type=purchase`,{method:"POST",headers,body:fd});setStatus("Bill uploaded. AI is extracting vendor and stock rows…");const x=await req(`/businesses/${ctx.business.id}/images/${d.id}/extract`,{method:"POST",headers});setRows(x.data?.rows||[]);if(x.data?.supplier_or_customer)setVendorName(x.data.supplier_or_customer);setStatus(x.data?.supplier_or_customer?`Bill processed. Vendor found: ${x.data.supplier_or_customer}. Review before submitting.`:"Bill processed, but vendor was not found. Enter Purchased from manually.")}catch(e:any){setStatus(`Upload failed: ${e.message}`)}finally{setBusy(false)}}
  async function receive(){setBusy(true);setStatus("Submitting purchase and updating inventory…");try{const invalid=rows.find(r=>!String(r.product_name||"").trim()||Number(r.quantity)<=0||Number(r.unit_price)<0);if(invalid){setStatus("Every purchase row needs a product name and quantity above 0.");return}let supplierId=supplier;if(vendorName.trim()){const vendor=await req(`/businesses/${ctx.business.id}/suppliers/resolve`,{method:"POST",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({name:vendorName.trim()})});supplierId=vendor.supplier.id}if(!supplierId){setStatus("Enter Purchased from or select an existing vendor before submitting.");return}const lines=[];for(const r of rows){let p=(ctx.products||[]).find((x:Row)=>x.name.toLowerCase()===r.product_name.toLowerCase());if(!p){const x=await req(`/businesses/${ctx.business.id}/products/resolve`,{method:"POST",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({store_id:ctx.store.id,name:r.product_name,unit:r.unit||null,mrp:Number(r.mrp||r.unit_price),price:Number(r.unit_price)})});p=x.product}lines.push({product_id:p.id,quantity:Number(r.quantity),unit_price:Number(r.unit_price)})}await req(`/businesses/${ctx.business.id}/purchases`,{method:"POST",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({store_id:ctx.store.id,supplier_id:supplierId,invoice_number:`DEALER-${Date.now()}`,paid:0,lines})});window.dispatchEvent(new Event("kirana:data-changed"));setStatus("Purchase submitted successfully. Vendor saved and inventory refreshed.")}catch(e:any){setStatus(e.message)}finally{setBusy(false)}}
  return <div className="panel smart-entry"><div className="purchase-head"><div><span className="eyebrow">DEALER</span><select value={supplier} onChange={e=>setSupplier(e.target.value)}>{(ctx.suppliers||[]).map((s:Row)=><option value={s.id} key={s.id}>{s.name}</option>)}</select></div><div><span className="eyebrow">PURCHASE DATE</span><input type="date" defaultValue={new Date().toISOString().slice(0,10)}/></div></div><div className="entry-choice single"><div><span className="eyebrow">HOW ARE YOU ENTERING THE DEALER STOCK?</span>{(["table","upload","text"] as const).map(x=><button disabled={busy} key={x} className={method===x?"choice active":"choice"} onClick={()=>setMethod(x)}>{x==="table"?"Write manually":x==="upload"?"Upload bill / CSV":"Write naturally with AI"}</button>)}</div></div>{method==="upload"&&<div className="upload-zone"><b>Upload dealer bill or stock CSV</b><FilePicker accept="image/jpeg,image/png,image/webp,.csv" onPick={upload} busy={busy} label="Choose bill image or CSV"/></div>}{method==="text"&&<div className="natural-entry"><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="Coca Cola 2L 12 80"/><button className="primary" disabled={busy} onClick={parse}>{busy?<><i className="spinner"/> Mapping…</>:"Map purchase with AI"}</button></div>}<div className="entry-table"><div className="entry-tr head"><b>Product bought</b><b>Quantity</b><b>Buy price</b><span></span></div>{rows.map((r,i)=><div className="entry-tr" key={i}><input value={r.product_name} onChange={e=>update(i,"product_name",e.target.value)}/><input type="number" value={r.quantity} onChange={e=>update(i,"quantity",e.target.value)}/><input type="number" value={r.unit_price} onChange={e=>update(i,"unit_price",e.target.value)}/><button disabled={busy} onClick={()=>setRows(rows.filter((_,n)=>n!==i))}>×</button></div>)}</div><div className="entry-footer"><button className="ghost" disabled={busy} onClick={()=>setRows([...rows,{product_name:"",quantity:1,unit_price:0}])}>＋ Add product row</button><button className="primary" disabled={busy} onClick={receive}>{busy?<><i className="spinner"/> Updating inventory…</>:"Confirm purchase & add stock"}</button></div>{status&&<p className="entry-status"><span className={busy?"status-dot working":"status-dot"}/>{status}</p>}</div>
}

function PurchaseEntry(){
  const {headers,req,token}=SessionApi();
  const [ctx,setCtx]=useState<Row>({}),[supplier,setSupplier]=useState(""),[vendorName,setVendorName]=useState(""),[entryDate,setEntryDate]=useState(todayInput()),[paymentMode,setPaymentMode]=useState("cash");
  const [rows,setRows]=useState<Row[]>([]),[status,setStatus]=useState(""),[busy,setBusy]=useState(false);
  async function load(){const b=(await req("/businesses",{headers}))[0],stores=await req(`/businesses/${b.id}/stores`,{headers}),suppliers=await req(`/businesses/${b.id}/suppliers`,{headers}),products=await req(`/businesses/${b.id}/products`,{headers});setCtx({business:b,store:stores[0],suppliers,products})}
  useEffect(()=>{if(token)load().catch(e=>setStatus(e.message))},[token]);
  useEffect(()=>{const input=document.querySelector<HTMLInputElement>(".purchase-workspace input[type=date]");if(!input)return;input.max=todayInput();input.value=entryDate;const changed=()=>setEntryDate(input.value);input.addEventListener("change",changed);return()=>input.removeEventListener("change",changed)},[entryDate]);
  useEffect(()=>{const host=document.querySelector(".purchase-workspace .upload-zone");if(!host)return;let review=document.getElementById("purchase-payment-review");if(!review){review=document.createElement("div");review.id="purchase-payment-review";review.className="payment-review";review.innerHTML='<label>Payment mode<select aria-label="Purchase payment mode"><option value="cash">Cash</option><option value="upi">UPI</option><option value="supplier_credit">Udhaar</option></select></label><small>AI fills this from the bill. If absent, Cash is used.</small>';host.insertAdjacentElement("beforebegin",review)}const select=review.querySelector("select") as HTMLSelectElement;select.value=paymentMode;select.onchange=()=>setPaymentMode(select.value);return()=>{select.onchange=null}},[paymentMode,rows.length]);
  function update(i:number,k:string,v:any){setRows(rows.map((r,n)=>n===i?{...r,[k]:v}:r))}
  async function upload(file:File){setBusy(true);setStatus(`Uploading ${file.name}…`);try{if(file.name.toLowerCase().endsWith(".csv")){const raw=await file.text();setPaymentMode("cash");setRows(guardedRows(raw.split(/\r?\n/).filter(Boolean).slice(1).map(x=>{const [product_name,quantity,total_price,unit,trade_form]=x.split(",");return {product_name,quantity:Number(quantity),total_price:Number(total_price),unit,trade_form}})));setStatus("CSV processed. Payment defaulted to Cash. Review rows.");return}const fd=new FormData();fd.append("file",file);const doc=await req(`/businesses/${ctx.business.id}/images?store_id=${ctx.store.id}&document_type=purchase`,{method:"POST",headers,body:fd});setStatus("Bill uploaded. AI is extracting vendor, payment and products…");const extracted=await req(`/businesses/${ctx.business.id}/images/${doc.id}/extract`,{method:"POST",headers});setPaymentMode(normalizePaymentMode(extracted.data?.payment_mode,"purchases"));setRows(guardedRows((extracted.data?.rows||[]).map((r:Row)=>({...r,total_price:Number(r.total_price??r.amount??0)}))));const found=String(extracted.data?.supplier_or_customer||"").trim();if(found){setVendorName(found);setSupplier("");setStatus(`Bill processed. Vendor found: ${found}. Review payment mode.`)}else setStatus("Bill processed. Vendor was not visible—enter Purchased from manually.")}catch(e:any){setStatus(`Upload failed: ${e.message}`)}finally{setBusy(false)}}
  async function receive(){
    setBusy(true);setStatus("Purchase save ho rahi hai…");
    try{
      const invalid=rows.find(r=>!String(r.product_name||"").trim()||Number(r.quantity)<=0||Number(r.total_price)<0);
      if(invalid){setStatus("Har row mein product, zero se zyada quantity aur total price bharein.");return}
      let supplierId=supplier;
      if(vendorName.trim()){const v=await req(`/businesses/${ctx.business.id}/suppliers/resolve`,{method:"POST",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({name:vendorName.trim()})});supplierId=v.supplier.id}
      if(!supplierId){setStatus("Vendor chunein ya Purchased from mein naam likhein.");return}
      const currentProducts=await req(`/businesses/${ctx.business.id}/products`,{headers}),lines=[];
      for(const r of rows){
        const unitCost=Number(r.total_price)/Number(r.quantity),clean=(v:string)=>v.trim().toLocaleLowerCase("en-IN").replace(/\s+/g," "),label=variantName(r);
        let product=currentProducts.find((p:Row)=>clean(p.name)===clean(label));
        if(!product&&currentProducts.length){try{const matched=await req(`/businesses/${ctx.business.id}/products/match`,{method:"POST",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({name:label})});product=matched.product}catch{}}
        if(!product){setStatus(`Naya product “${label}” ban raha hai…`);const x=await req(`/businesses/${ctx.business.id}/products/resolve`,{method:"POST",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({store_id:ctx.store.id,name:label,unit:r.trade_form==="packed"?"packet":r.unit||null,mrp:Number(r.mrp||0),price:0})});product=x.product;currentProducts.push(product)}
        lines.push({product_id:product.id,quantity:Number(r.quantity),unit_price:unitCost});
      }
      await req(`/businesses/${ctx.business.id}/purchases`,{method:"POST",headers:{...headers,"Content-Type":"application/json"},body:JSON.stringify({store_id:ctx.store.id,supplier_id:supplierId,invoice_number:`DEALER-${Date.now()}`,transaction_date:entryDate,payment_mode:paymentMode,paid:0,lines})});
      localStorage.removeItem(`kirana-purchase-draft-${ctx.business.id}`);setRows([]);await load();window.dispatchEvent(new Event("kirana:data-changed"));setStatus(`${lines.length} products ki purchase save ho gayi. Ab sales image submit kar sakte hain.`);
    }catch(e:any){setStatus(e.message)}finally{setBusy(false)}
  }
  return <div className="purchase-workspace"><div className="panel smart-entry"><div className="purchase-head"><div><span className="eyebrow">EXISTING VENDOR</span><select value={supplier} onChange={e=>{setSupplier(e.target.value);if(e.target.value)setVendorName("")}}><option value="">Select vendor</option>{(ctx.suppliers||[]).map((s:Row)=><option value={s.id} key={s.id}>{s.name} · {s.id.slice(0,8)}</option>)}</select></div><div><span className="eyebrow">PURCHASED FROM</span><input value={vendorName} onChange={e=>{setVendorName(e.target.value);if(e.target.value)setSupplier("")}} placeholder="AI fills from bill; add it here if missing"/></div><div><span className="eyebrow">PURCHASE DATE</span><input type="date" defaultValue={new Date().toISOString().slice(0,10)}/></div></div><div className="upload-zone"><b>Upload dealer bill or stock CSV</b><p>CSV columns: product_name, quantity, total_price, unit, form (optional)</p><FilePicker accept="image/jpeg,image/png,image/webp,.csv" onPick={upload} busy={busy} label="Choose bill image or CSV"/></div>{rows.length>0&&<><div className="entry-table"><div className="entry-tr purchase-cost guarded head"><b>Product bought</b><b>Form</b><b>Quantity</b><b>Total price</b><b>Price / unit</b><span/></div>{rows.map((r,i)=>{const perUnit=Number(r.quantity)>0?Number(r.total_price||0)/Number(r.quantity):0;return <div className="entry-tr purchase-cost guarded" key={i}><input value={r.product_name||""} onChange={e=>setRows(rows.map((x,n)=>n===i?guardedRow({...x,product_name:e.target.value,trade_form:""}):x))}/><div className="form-guard"><select value={r.trade_form||"standard"} onChange={e=>setRows(rows.map((x,n)=>n===i?{...x,trade_form:e.target.value,form_confidence:"corrected"}:x))}><option value="standard">Standard</option><option value="loose">Loose</option><option value="packed">Packed</option></select>{r.form_confidence==="assumed"&&<small>⚠ Assumed</small>}</div><input type="number" min="0" value={r.quantity||0} onChange={e=>update(i,"quantity",e.target.value)}/><input type="number" min="0" value={r.total_price||0} onChange={e=>update(i,"total_price",e.target.value)}/><output>{money(perUnit)}</output><button disabled={busy} onClick={()=>setRows(rows.filter((_,n)=>n!==i))}>×</button></div>})}</div><p className="guard-note">For sugar, salt, rice, flour and pulses, unclear weight entries default to <b>Loose</b>. Correct the Form here before confirming.</p><div className="entry-footer"><button className="primary" disabled={busy} onClick={receive}>{busy?"Updating inventory…":"Confirm purchase & add stock"}</button></div></>}{status&&<p className="entry-status"><span className={busy?"status-dot working":"status-dot"}/>{status}</p>}</div><TransactionManager kind="purchases"/><VendorTable/></div>
}
